import pulp

# Data
shipments = ['S1', 'S2', 'S3']
hubs = ['H1', 'H2', 'H3']

# Processing times: p[shipment][hub]
p = {
    'S1': {'H2': 2, 'H1': 2, 'H3': 6},
    'S2': {'H2': 7, 'H1': 6, 'H3': 10},
    'S3': {'H3': 8, 'H1': 9, 'H2': 5}
}

# Sequence of hubs for each shipment
sequence = {
    'S1': ['H2', 'H1', 'H3'],
    'S2': ['H2', 'H1', 'H3'],
    'S3': ['H3', 'H1', 'H2']
}

# Big M
M = 55

# Model
model = pulp.LpProblem("JobShopScheduling", pulp.LpMinimize)

# Decision variables
x = {}
for i in shipments:
    for m in hubs:
        x[(i, m)] = pulp.LpVariable(f"start_{i}_{m}", lowBound=0, cat='Continuous')

y = {}
for i in shipments:
    for j in shipments:
        if i < j:
            for m in hubs:
                y[(i, j, m)] = pulp.LpVariable(f"precede_{i}_{j}_{m}", cat='Binary')

Cmax = pulp.LpVariable("Cmax", lowBound=0, cat='Continuous')

# Objective
model += Cmax

# Precedence constraints within each shipment
for i in shipments:
    seq = sequence[i]
    for k in range(len(seq) - 1):
        m1 = seq[k]
        m2 = seq[k + 1]
        model += x[(i, m1)] + p[i][m1] <= x[(i, m2)]

# Disjunctive constraints for each hub
for m in hubs:
    for i in shipments:
        for j in shipments:
            if i < j:
                if m in p[i] and m in p[j]:
                    model += x[(i, m)] + p[i][m] <= x[(j, m)] + M * (1 - y[(i, j, m)])
                    model += x[(j, m)] + p[j][m] <= x[(i, m)] + M * y[(i, j, m)]

# Makespan constraints
for i in shipments:
    last_hub = sequence[i][-1]
    model += x[(i, last_hub)] + p[i][last_hub] <= Cmax

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Optimal makespan:", pulp.value(Cmax))
print("\nStart times:")
for i in shipments:
    for m in hubs:
        if m in p[i]:
            print(f"{i} at {m}: start = {pulp.value(x[(i, m)]):.2f}, duration = {p[i][m]}")

print("\nSequence at each hub (by start time):")
for m in hubs:
    jobs_at_hub = [(i, pulp.value(x[(i, m)])) for i in shipments if m in p[i]]
    jobs_at_hub.sort(key=lambda tup: tup[1])
    print(f"{m}: {', '.join([f'{job[0]} (start {job[1]:.2f})' for job in jobs_at_hub])}")

import pulp

# Data from the problem
phases_data = [
    [("Team4", 5), ("Team5", 3), ("Team1", 6), ("Team3", 2), ("Team2", 3), ("Team6", 1), ("Team7", 3)],
    [("Team5", 2), ("Team7", 8), ("Team2", 9), ("Team1", 6), ("Team4", 6), ("Team6", 2), ("Team3", 1)],
    [("Team2", 8), ("Team7", 6), ("Team4", 9), ("Team3", 6), ("Team6", 2), ("Team1", 2), ("Team5", 5)],
    [("Team5", 5), ("Team4", 4), ("Team2", 8), ("Team3", 6), ("Team7", 5), ("Team1", 7), ("Team6", 10)],
    [("Team2", 6), ("Team1", 6), ("Team4", 7), ("Team3", 5), ("Team5", 6), ("Team7", 7), ("Team6", 5)],
    [("Team7", 6), ("Team1", 4), ("Team4", 3), ("Team3", 6), ("Team6", 8), ("Team2", 4), ("Team5", 2)],
    [("Team6", 7), ("Team4", 9), ("Team7", 5), ("Team5", 8), ("Team3", 4), ("Team2", 6), ("Team1", 9)]
]

# Convert team names to indices 0..6 for easier handling
team_name_to_idx = {"Team1": 0, "Team2": 1, "Team3": 2, "Team4": 3, "Team5": 4, "Team6": 5, "Team7": 6}

# Processing times and machine assignments
n_jobs = 7
n_tasks = 7
p = {}  # p[job][task] = duration
m = {}  # m[job][task] = machine index
for j in range(n_jobs):
    p[j] = {}
    m[j] = {}
    for k in range(n_tasks):
        team_name, duration = phases_data[j][k]
        p[j][k] = duration
        m[j][k] = team_name_to_idx[team_name]

# Big M: sum of all processing times
M = sum(p[j][k] for j in range(n_jobs) for k in range(n_tasks))

# Model
model = pulp.LpProblem("ConstructionProjectScheduling", pulp.LpMinimize)

# Decision variables
S = {}  # start times
for j in range(n_jobs):
    for k in range(n_tasks):
        S[(j, k)] = pulp.LpVariable(f"S_{j}_{k}", lowBound=0, cat='Integer')

# Makespan variable
T = pulp.LpVariable("T", lowBound=0, cat='Integer')

# Binary variables for sequencing on same machine
# Only for pairs of jobs j1 < j2, and tasks on same machine
y_vars = {}
for j1 in range(n_jobs):
    for k1 in range(n_tasks):
        for j2 in range(j1 + 1, n_jobs):
            for k2 in range(n_tasks):
                if m[j1][k1] == m[j2][k2]:
                    y_vars[(j1, k1, j2, k2)] = pulp.LpVariable(f"y_{j1}_{k1}_{j2}_{k2}", cat='Binary')

# Objective: minimize makespan
model += T

# Precedence within each job
for j in range(n_jobs):
    for k in range(1, n_tasks):
        model += S[(j, k)] >= S[(j, k-1)] + p[j][k-1]

# Makespan definition
for j in range(n_jobs):
    model += T >= S[(j, n_tasks-1)] + p[j][n_tasks-1]

# Disjunctive constraints for tasks on same machine
for j1 in range(n_jobs):
    for k1 in range(n_tasks):
        for j2 in range(j1 + 1, n_jobs):
            for k2 in range(n_tasks):
                if m[j1][k1] == m[j2][k2]:
                    y = y_vars[(j1, k1, j2, k2)]
                    # If y=1, then (j1,k1) before (j2,k2)
                    model += S[(j2, k2)] >= S[(j1, k1)] + p[j1][k1] - M * (1 - y)
                    # If y=0, then (j2,k2) before (j1,k1)
                    model += S[(j1, k1)] >= S[(j2, k2)] + p[j2][k2] - M * y

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Optimal makespan:", pulp.value(T))

# Print schedule
print("\nStart times for each phase (job) and task:")
for j in range(n_jobs):
    print(f"Phase {j+1}:", end="")
    for k in range(n_tasks):
        print(f" {pulp.value(S[(j, k)]):.0f}", end="")
    print()

# Print team schedules
print("\nTeam schedules (job, task, start, duration):")
teams_schedules = {t: [] for t in range(7)}
for j in range(n_jobs):
    for k in range(n_tasks):
        team_idx = m[j][k]
        start = pulp.value(S[(j, k)])
        duration = p[j][k]
        teams_schedules[team_idx].append((j, k, start, duration))

for t in range(7):
    teams_schedules[t].sort(key=lambda x: x[2])  # sort by start time
    print(f"Team{t+1}: {teams_schedules[t]}")

