import pulp

# Data
routes = [1, 2, 3, 4]
stages = [1, 2, 3, 4]
hubs = ['A', 'B', 'C', 'D']

# Processing times p[r][s] (1-based indexing)
p = {
    (1,1):5, (1,2):5, (1,3):7, (1,4):7,
    (2,1):4, (2,2):5, (2,3):6, (2,4):1,
    (3,1):8, (3,2):10, (3,3):2, (3,4):3,
    (4,1):7, (4,2):8, (4,3):1, (4,4):2
}

# Hub for each (r,s)
hub = {
    (1,1):'C', (1,2):'B', (1,3):'A', (1,4):'D',
    (2,1):'D', (2,2):'A', (2,3):'C', (2,4):'B',
    (3,1):'A', (3,2):'B', (3,3):'C', (3,4):'D',
    (4,1):'C', (4,2):'B', (4,3):'A', (4,4):'D'
}

# Big M (sum of all durations)
M = sum(p.values())

# Model
model = pulp.LpProblem("JobShopMinMakespan", pulp.LpMinimize)

# Variables
S = pulp.LpVariable.dicts("Start", [(r,s) for r in routes for s in stages], lowBound=0, cat='Continuous')
Cmax = pulp.LpVariable("Cmax", lowBound=0, cat='Continuous')

# Binary precedence variables: y[(r,s,r',s')] = 1 if (r,s) before (r',s') on same hub
y_vars = {}
for r in routes:
    for s in stages:
        for rp in routes:
            for sp in stages:
                if r < rp and hub[(r,s)] == hub[(rp,sp)]:
                    y_vars[(r,s,rp,sp)] = pulp.LpVariable(f"y_{r}_{s}_{rp}_{sp}", cat='Binary')

# Objective
model += Cmax

# Constraints: route precedence
for r in routes:
    for s in range(1, 4):
        model += S[(r,s)] + p[(r,s)] <= S[(r,s+1)]

# Constraints: hub capacity (disjunctive)
for r in routes:
    for s in stages:
        for rp in routes:
            for sp in stages:
                if r < rp and hub[(r,s)] == hub[(rp,sp)]:
                    y = y_vars[(r,s,rp,sp)]
                    model += S[(r,s)] + p[(r,s)] <= S[(rp,sp)] + M * (1 - y)
                    model += S[(rp,sp)] + p[(rp,sp)] <= S[(r,s)] + M * y

# Constraints: makespan definition
for r in routes:
    model += S[(r,4)] + p[(r,4)] <= Cmax

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Optimal makespan:", pulp.value(Cmax))
print("\nStart times:")
for r in routes:
    for s in stages:
        print(f"Route {r}, Stage {s} (Hub {hub[(r,s)]}, Dur {p[(r,s)]}): Start = {pulp.value(S[(r,s)]):.2f}")
